package com.example.data.remote

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.RequestBody.Companion.toRequestBody
import org.json.JSONObject
import java.util.concurrent.TimeUnit

/** Summaries are generated by the service, never by a user-supplied device API key. */
class NewsSummaryApiService(private val httpClient: OkHttpClient) {
    private val summaryClient = httpClient.newBuilder()
        .connectTimeout(6, TimeUnit.SECONDS)
        .readTimeout(32, TimeUnit.SECONDS)
        .callTimeout(35, TimeUnit.SECONDS)
        .build()
    suspend fun summarize(title: String, articleUrl: String, sourceText: String): String? = withContext(Dispatchers.IO) {
        if (title.isBlank() || articleUrl.isBlank()) return@withContext null

        try {
            val payload = JSONObject()
                .put("title", title)
                .put("url", articleUrl)
                .put("sourceText", sourceText.take(MAX_SOURCE_CHARS))
            val request = Request.Builder()
                .url("${ApiGatewayConfig.BASE_URL}/v1/summary")
                .header("Accept", "application/json")
                .post(payload.toString().toRequestBody(JSON))
                .build()

            summaryClient.newCall(request).execute().use { response ->
                if (!response.isSuccessful) return@withContext null
                val body = response.body?.string().orEmpty()
                if (body.isBlank()) return@withContext null
                JSONObject(body).optString("summary").trim().takeIf { it.length >= MIN_SUMMARY_CHARS }
            }
        } catch (_: Exception) {
            null
        }
    }

    private companion object {
        const val MAX_SOURCE_CHARS = 12_000
        const val MIN_SUMMARY_CHARS = 50
        val JSON = "application/json; charset=utf-8".toMediaType()
    }
}

